import fixtureJson from '../../oracles/fixtures/statistics-rate-smoothing.json';
import {decodeOracleFixture} from '../../oracles/oracle-fixture';

/**
 * esda `Spatial_Rate` and `Spatial_Empirical_Bayes` on a 6x6 queen lattice (`lat2W(6, 6,
 * rook=False)`) with numpy `default_rng(42)` populations and fixed events (rows 3 and 20 have zero
 * events). Generated by `test/oracles/statistics-rate-smoothing.py`.
 */
export type SpatialEBLatticeReference = {
  events: number[];
  populations: number[];
  offsets: number[];
  neighbors: number[];
  spatialRate: number[];
  smoothed: number[];
};

const fixture = decodeOracleFixture<{
  generator: string;
  versions: Record<string, string>;
  tolerances: Record<string, unknown>;
  reference: {lattice: SpatialEBLatticeReference};
}>(fixtureJson);

export const ESDA_SPATIAL_EB_LATTICE = fixture.reference.lattice;
